// Split batches into individual items for processing
const batches = $json.batches || [];
return batches.map(batch => ({ json: batch }));

// ============================================
// MERGE BATCH INFO WITH STATUS
// Mode Redis: utilise redis_channel pour notification
// ============================================

const statusResponse = $input.first().json;
const batchInfo = $('Split Batches').first().json;

// Parse metadata si c'est une string JSON
let metadata = batchInfo.metadata;
if (typeof metadata === 'string') {
  try { metadata = JSON.parse(metadata); } catch(e) { metadata = {}; }
}

return {
  // Original batch info from Redis
  redis_id: batchInfo.redis_id,
  batch_id: batchInfo.batch_id,
  correlation_id: batchInfo.correlation_id,
  redis_channel: batchInfo.redis_channel || metadata?.redis_channel || 'llm:results:stream',
  api_key: batchInfo.api_key,
  model: batchInfo.model,
  metadata: metadata,
  submitted_at: batchInfo.submitted_at,

  // Status from Anthropic
  processing_status: statusResponse.processing_status,
  request_counts: statusResponse.request_counts,
  results_url: statusResponse.results_url,
  ended_at: statusResponse.ended_at,
  created_at: statusResponse.created_at,
  expires_at: statusResponse.expires_at,

  // Error handling
  has_error: !!statusResponse.error,
  error: statusResponse.error
};

// ============================================
// PROCESS BATCH RESULTS - Extract files and text
// FIX: Handle data as JSON string
// FIX: Extract files from bash_code_execution_tool_result
// ============================================

const resultsRaw = $input.first().json;
const batchInfo = $('Merge Info').first().json;

// Handle undefined/null input
if (!resultsRaw) {
  return {
    success: false,
    batch_id: batchInfo.batch_id,
    correlation_id: batchInfo.correlation_id,
    redis_id: batchInfo.redis_id,
    error: { code: 'NO_RESULTS', message: 'Results response was empty' },
    metadata: batchInfo.metadata
  };
}

// Parse results - handle various formats
let results = [];

// Case 1: resultsRaw.data is a JSON string (JSONL format from Anthropic)
if (resultsRaw.data && typeof resultsRaw.data === 'string') {
  results = resultsRaw.data.split('\n').filter(line => line.trim()).map(line => JSON.parse(line));
}
// Case 2: resultsRaw itself is a string
else if (typeof resultsRaw === 'string') {
  results = resultsRaw.split('\n').filter(line => line.trim()).map(line => JSON.parse(line));
}
// Case 3: resultsRaw.data is an array
else if (resultsRaw.data && Array.isArray(resultsRaw.data)) {
  results = resultsRaw.data;
}
// Case 4: resultsRaw is an array
else if (Array.isArray(resultsRaw)) {
  results = resultsRaw;
}
// Case 5: resultsRaw has custom_id directly (single result)
else if (resultsRaw.custom_id) {
  results = [resultsRaw];
}
// Case 6: Fallback - wrap as array
else {
  results = [resultsRaw];
}

// Ensure results is an array
if (!Array.isArray(results)) {
  results = [];
}

// Find our result by custom_id (correlation_id)
// --- mode multi-résultats (batch N requêtes) ---
if (batchInfo.metadata && batchInfo.metadata.multi) {
  const out = results.map(r => {
    const t = r && r.result && r.result.type;
    if (t === 'succeeded') {
      const msg = r.result.message || {};
      const text = (msg.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
      return { custom_id: r.custom_id, ok: true, text };
    }
    return { custom_id: r && r.custom_id, ok: false, error: (r && r.result && r.result.error) || { code: String(t || 'unknown') } };
  });
  return {
    success: true, multi: true,
    batch_id: batchInfo.batch_id, correlation_id: batchInfo.correlation_id,
    callback_url: batchInfo.callback_url, redis_id: batchInfo.redis_id, api_key: batchInfo.api_key,
    results: out, metadata: batchInfo.metadata,
    _trace: { batch_id: batchInfo.batch_id, completed_at: new Date().toISOString(), count: out.length, ok: out.filter(x => x.ok).length }
  };
}
const ourResult = results.find(r => r && r.custom_id === batchInfo.correlation_id);

if (!ourResult) {
  return {
    success: false,
    batch_id: batchInfo.batch_id,
    correlation_id: batchInfo.correlation_id,
    callback_url: batchInfo.callback_url,
    redis_id: batchInfo.redis_id,
    api_key: batchInfo.api_key,
    error: {
      code: 'RESULT_NOT_FOUND',
      message: `No result found for custom_id: ${batchInfo.correlation_id}. Available: ${results.map(r => r?.custom_id).join(', ')}`
    },
    metadata: batchInfo.metadata
  };
}

// Check result type
const resultType = ourResult.result?.type;

if (resultType === 'errored') {
  return {
    success: false,
    batch_id: batchInfo.batch_id,
    correlation_id: batchInfo.correlation_id,
    callback_url: batchInfo.callback_url,
    redis_id: batchInfo.redis_id,
    api_key: batchInfo.api_key,
    error: ourResult.result.error || { code: 'BATCH_ERROR', message: 'Batch processing failed' },
    metadata: batchInfo.metadata
  };
}

if (resultType === 'expired') {
  return {
    success: false,
    batch_id: batchInfo.batch_id,
    correlation_id: batchInfo.correlation_id,
    callback_url: batchInfo.callback_url,
    redis_id: batchInfo.redis_id,
    api_key: batchInfo.api_key,
    error: { code: 'BATCH_EXPIRED', message: 'Batch expired before processing' },
    metadata: batchInfo.metadata
  };
}

if (resultType === 'canceled') {
  return {
    success: false,
    batch_id: batchInfo.batch_id,
    correlation_id: batchInfo.correlation_id,
    callback_url: batchInfo.callback_url,
    redis_id: batchInfo.redis_id,
    api_key: batchInfo.api_key,
    error: { code: 'BATCH_CANCELED', message: 'Batch was canceled' },
    metadata: batchInfo.metadata
  };
}

// Extract message content
const message = ourResult.result?.message || {};
const textContent = [];
const fileRefs = [];

// Helper to guess filename from format in metadata
const format = batchInfo.metadata?.format || 'docx';
const defaultFilename = `document.${format}`;

for (const block of (message.content || [])) {
  if (block.type === 'text') {
    textContent.push(block.text);
  }

  // Legacy format: tool_result with output.file_id
  if (block.type === 'tool_result' && block.output?.file_id) {
    fileRefs.push({
      file_id: block.output.file_id,
      name: block.output.name || defaultFilename,
      mime_type: block.output.mime_type || 'application/octet-stream',
      size: block.output.size
    });
  }

  // NEW: Extract files from bash_code_execution_tool_result
  // FIX: Structure is block.content.content (nested), not block.content directly
  // Real structure: { type: 'bash_code_execution_tool_result', content: { type: 'bash_code_execution_result', content: [...] } }
  if (block.type === 'bash_code_execution_tool_result') {
    const bashContent = block.content?.content;
    if (Array.isArray(bashContent)) {
      for (const item of bashContent) {
        if (item.type === 'bash_code_execution_output' && item.file_id) {
          fileRefs.push({
            file_id: item.file_id,
            name: item.name || defaultFilename,
            mime_type: item.mime_type || (format === 'pdf' ? 'application/pdf' : 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'),
            size: item.size
          });
        }
      }
    }
  }

  // NEW: Extract files from text_editor_code_execution_tool_result
  if (block.type === 'text_editor_code_execution_tool_result' && block.content) {
    if (block.content.file_id) {
      fileRefs.push({
        file_id: block.content.file_id,
        name: block.content.name || defaultFilename,
        mime_type: block.content.mime_type || 'application/octet-stream',
        size: block.content.size
      });
    }
  }
}

// Check container_result for files
if (message.container_result?.files) {
  for (const file of message.container_result.files) {
    fileRefs.push({
      file_id: file.file_id,
      name: file.name,
      mime_type: file.mime_type,
      size: file.size
    });
  }
}

// Deduplicate files by file_id (keep first occurrence)
const seenFileIds = new Set();
const uniqueFileRefs = fileRefs.filter(f => {
  if (seenFileIds.has(f.file_id)) return false;
  seenFileIds.add(f.file_id);
  return true;
});

// Build file download URLs
const files = uniqueFileRefs.map(f => ({
  file_id: f.file_id,
  filename: f.name,
  mime_type: f.mime_type,
  size_bytes: f.size || 0,
  download_url: `https://api.anthropic.com/v1/files/${f.file_id}/content`
}));

return {
  success: true,
  batch_id: batchInfo.batch_id,
  correlation_id: batchInfo.correlation_id,
  callback_url: batchInfo.callback_url,
  redis_id: batchInfo.redis_id,
  api_key: batchInfo.api_key,

  // Response data for callback
  content: [{ type: 'text', text: textContent.join('\n') }],
  files: files,
  has_files: files.length > 0,

  provider: 'anthropic',
  model: message.model || batchInfo.model,
  usage: message.usage || { input_tokens: 0, output_tokens: 0 },
  stop_reason: message.stop_reason || 'end_turn',
  metadata: batchInfo.metadata,

  _trace: {
    batch_id: batchInfo.batch_id,
    submitted_at: batchInfo.submitted_at,
    completed_at: new Date().toISOString(),
    files_count: files.length
  }
};

// ============================================
// OPTION B — Télécharge les fichiers depuis Anthropic avec l'api_key LOCAL
// et les publie en base64 (files[].data). L'api_key ne quitte JAMAIS n8n.
// _get_discord_file (plugin) gère déjà le champ `data` base64.
// ============================================
const src = $input.first().json;
const apiKey = src.api_key;
const outFiles = [];

for (const f of (src.files || [])) {
  if (!f.download_url) { outFiles.push(f); continue; }
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: f.download_url,
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'anthropic-beta': 'files-api-2025-04-14' },
      encoding: 'arraybuffer',
      returnFullResponse: true,
    });
    const b64 = Buffer.from(response.body).toString('base64');
    outFiles.push({
      file_id: f.file_id,
      filename: f.filename,
      mime_type: f.mime_type,
      size_bytes: f.size_bytes || (response.body ? response.body.length : 0),
      data: b64,                 // base64 → consommé par le plugin
    });
  } catch (e) {
    // échec de téléchargement : on garde la trace, pas de data, pas de crash
    outFiles.push({
      file_id: f.file_id,
      filename: f.filename,
      mime_type: f.mime_type,
      download_error: (e && e.message) ? e.message : String(e),
    });
  }
}

return [{ json: { ...src, files: outFiles, has_files: outFiles.length > 0 } }];
